Translate("ptBR", "atal-alarion", {
	title = "Atal'alarion",
	subtitle = "Guardião do Ídolo",
	found = [=[O nível mais baixo do Templo de Atal'Hakkar, sob o círculo de estátuas]=],
	hint = [=[Desvende o segredo das estátuas de serpente no nível mais baixo do templo.]=],
	allegiance = "Os Atal'ai",
	sections = {
		{
			title = "Resumo",
			text = [=[Atal'alarion é o guardião do ídolo que jaz no fundo do templo afogado. Em torno de um salão redondo há seis sacadas, cada uma com uma estátua de serpente na borda. Na base do salão aguarda um altar de {link:hakkar}Hakkar{/link}. Quem desperta as estátuas do jeito errado é derrubado por armadilhas. Quem encontra a ordem certa faz surgir o guardião. Ele é um bruto enorme, e promete se banquetear com os ossos dos intrusos.]=],
		},
		{
			title = "Importância",
			text = [=[Atal'alarion guarda o tesouro dos Atal'ai. O estudioso goblin {link:marvon-rivetseeker}Marvon Rivetseeker{/link} foi o primeiro de fora a encontrar o círculo, e quase morreu por isso.]=],
		},
	},
	chapters = {
		{
			title = "O Segredo do Círculo",
			hint = "Ajude o estudioso goblin de Tanaris a destravar o altar.",
			text = [=[{link:marvon-rivetseeker}Marvon{/link} encaixou uma ficha de pedra no altar de {link:hakkar}Hakkar{/link}, e com ela despertou um padrão de luzes. Quando as estátuas foram tocadas na ordem que as luzes revelaram, o guardião se ergueu. Atrás do olho do ídolo jazia o tesouro dos Atal'ai.]=],
		},
	},
	mentions = {
		{ text = "Rumo às {link:blackfathom-deeps}Profundezas{/link}" },
		{ text = "Um Ingrediente Melhor" },
	},
	bonds = {
		{ id = "hakkar", name = "Hakkar", note = "o deus cujo altar ele guarda" },
	},
})

